insert into glossaire (questionnaire_id, id, libelle, categorie, definition, exemple) values
  ('v1', '3c', '3C (méthode des)', 'Objectifs', 'Méthode de rédaction des objectifs pédagogiques en trois composantes : Comportement observable (verbe d''action de Bloom), Conditions de réalisation (contexte, ressources, contraintes), Critères de réussite (mesurables).', '« Établir (C) la déclaration de TVA mensuelle à partir de 20 factures et du logiciel comptable (C), sans erreur de taux et en moins de 30 minutes (C) ».'),
  ('v1', 'accessibilite-numerique', 'Accessibilité numérique', 'Accessibilité', 'Capacité d''un contenu numérique à être utilisé par toute personne, y compris en situation de handicap (visuel, auditif, moteur, cognitif), avec ou sans aide technique.', 'Une vidéo sous-titrée, des images décrites par un texte alternatif et une navigation possible au clavier seul.'),
  ('v1', 'accord-confidentialite', 'Accord de confidentialité', 'Juridique', 'Contrat par lequel le prestataire s''engage à ne pas divulguer les informations sensibles transmises par le client pendant et après la mission.', 'Un cabinet comptable exige un accord avant de fournir de vrais dossiers clients servant de cas pratiques.'),
  ('v1', 'afest', 'AFEST', 'Modalités', 'Action de formation en situation de travail. Elle alterne des mises en situation réelles au poste et des phases réflexives, hors production, animées par un accompagnateur, pour analyser ce qui a été fait.', 'Une assistante comptable réalise un rapprochement bancaire réel, puis analyse avec son tuteur les écarts rencontrés et la méthode suivie.'),
  ('v1', 'aif', 'AIF (Aide individuelle à la formation)', 'Financement', 'Aide de France Travail qui finance tout ou partie d''une formation pour un demandeur d''emploi lorsque les autres dispositifs ne suffisent pas.', 'Un demandeur d''emploi obtient une AIF pour suivre un module de paie qui conditionne son embauche.'),
  ('v1', 'allegement', 'Allègement de parcours', 'Ingénierie', 'Réduction de la durée ou du contenu d''un parcours pour un apprenant qui maîtrise déjà une partie des compétences, constatée par un positionnement.', 'Un stagiaire qui a déjà validé le bloc « comptabilité courante » ne suit que les modules de fiscalité.'),
  ('v1', 'alternance', 'Alternance', 'Modalités', 'Organisation qui combine des périodes en centre de formation et des périodes en entreprise, sous contrat d''apprentissage, de professionnalisation ou dans le cadre de Pro-A.', 'Un rythme de deux jours en formation et trois jours en entreprise pendant douze mois.'),
  ('v1', 'alternant', 'Alternant', 'Modalités', 'Personne en contrat d''apprentissage ou de professionnalisation qui partage son temps entre l''entreprise et l''organisme de formation.', 'Une apprentie en BTS Gestion de la PME, présente en cabinet trois jours par semaine.'),
  ('v1', 'andragogie', 'Andragogie', 'Pédagogie', 'Science et art d''aider les adultes à apprendre. Elle s''appuie sur leur expérience, leur besoin de comprendre l''utilité de ce qu''ils apprennent et leur autonomie (Malcolm Knowles).', 'Partir d''un problème réel rencontré par les participants plutôt que d''un cours théorique.'),
  ('v1', 'appel-offres', 'Appel d''offres', 'Administratif', 'Procédure par laquelle un acheteur, public ou privé, met en concurrence plusieurs prestataires sur la base d''un cahier des charges formalisé et de critères de sélection.', 'Une collectivité publie une consultation pour former ses agents à la bureautique, avec une date limite de réponse.'),
  ('v1', 'asynchrone', 'Asynchrone', 'Modalités', 'Modalité où l''apprenant se forme à son rythme, sans interaction en temps réel avec le formateur.', 'Un parcours de vidéos et de quiz à suivre sur deux semaines.'),
  ('v1', 'attestation-fin-formation', 'Attestation de fin de formation', 'Administratif', 'Document remis au stagiaire à l''issue de la formation. Il précise les objectifs, la nature, la durée de l''action et les résultats de l''évaluation des acquis.', '« Madame X a suivi 21 heures de formation Excel et atteint 4 objectifs sur 5 ».'),
  ('v1', 'audit', 'Audit', 'Prestations', 'Examen méthodique d''une organisation, d''un processus ou d''un dispositif au regard d''un référentiel, qui aboutit à des constats et des recommandations.', 'Audit du dispositif de formation interne d''une PME au regard de ses obligations légales.'),
  ('v1', 'audit-blanc', 'Audit blanc', 'Prestations', 'Simulation d''un audit officiel, réalisée dans les mêmes conditions, pour repérer les non-conformités avant le passage de l''auditeur certificateur.', 'Un audit blanc Qualiopi un mois avant l''audit de surveillance, avec rapport des preuves manquantes par indicateur.'),
  ('v1', 'banque-questions', 'Banque de questions', 'Conception', 'Ensemble structuré de questions classées par compétence et par niveau, dans lequel une plateforme pioche pour générer des évaluations variées.', '120 questions Excel classées en trois niveaux ; chaque test tire 5 questions par niveau au hasard.'),
  ('v1', 'besoin-formation', 'Besoin de formation', 'Besoin', 'Écart de compétences entre la situation actuelle et la situation attendue, qu''une formation peut combler. Un écart dû à l''organisation, aux outils ou au management n''est pas un besoin de formation.', 'Des erreurs de TVA dues à une méconnaissance des règles relèvent de la formation ; des erreurs dues à un logiciel mal paramétré n''en relèvent pas.'),
  ('v1', 'blended-learning', 'Blended learning', 'Modalités', 'Formation hybride qui combine présentiel et distanciel (synchrone ou asynchrone) dans un même parcours conçu comme un tout.', 'Des modules e-learning le matin, une classe virtuelle par semaine et deux journées en présentiel pour les mises en situation.'),
  ('v1', 'bloc-competences', 'Bloc de compétences', 'Certification', 'Ensemble homogène et cohérent de compétences d''une certification RNCP, qui peut être évalué et validé séparément.', 'Le bloc « Assurer les travaux courants de comptabilité » d''un titre professionnel, validable seul.'),
  ('v1', 'bloom', 'Bloom (taxonomie de)', 'Objectifs', 'Classification des niveaux d''apprentissage, du plus simple au plus complexe : se souvenir, comprendre, appliquer, analyser, évaluer, créer. Elle fournit les verbes d''action des objectifs pédagogiques.', '« Calculer » relève du niveau appliquer ; « justifier un choix d''amortissement » relève du niveau évaluer.'),
  ('v1', 'cartographie-competences', 'Cartographie des compétences', 'Ingénierie', 'Représentation visuelle des compétences d''un métier ou d''un parcours, organisées par domaines et niveaux, qui sert de base à la conception.', 'Un schéma qui relie les 4 domaines d''un poste de gestionnaire de paie à leurs 18 compétences.'),
  ('v1', 'catalogue', 'Catalogue (formation)', 'Modalités', 'Formation standard, au programme déjà établi, proposée telle quelle à plusieurs clients.', '« Excel intermédiaire, 14 heures », au même programme pour toutes les entreprises.'),
  ('v1', 'ccn', 'CCN (Convention collective nationale)', 'Administratif', 'Accord négocié entre partenaires sociaux d''une branche, qui fixe des règles applicables aux salariés du secteur, y compris en matière de formation.', 'La convention collective des organismes de formation, identifiée par son numéro IDCC 1516.'),
  ('v1', 'certificat-realisation', 'Certificat de réalisation', 'Administratif', 'Document signé par l''organisme de formation qui atteste que l''action a bien été réalisée. Il est exigé par les financeurs pour déclencher le paiement.', 'Le certificat transmis à l''OPCO avec la facture pour obtenir le remboursement.'),
  ('v1', 'certificateur', 'Certificateur', 'Certification', 'Organisme propriétaire d''une certification enregistrée au RNCP ou au RS. Il en définit le référentiel et les modalités d''évaluation, et délivre le diplôme ou le titre.', 'Le ministère du Travail est le certificateur des titres professionnels.'),
  ('v1', 'cession-droits', 'Cession de droits', 'Juridique', 'Transfert, par contrat, de tout ou partie des droits d''auteur sur une œuvre (supports, vidéos, modules) au client, pour des usages, une durée et un territoire précisés.', 'Le client achète les droits d''exploitation d''un module e-learning pour le diffuser librement à ses salariés pendant cinq ans.'),
  ('v1', 'charte-graphique', 'Charte graphique', 'Juridique', 'Document qui fixe l''identité visuelle d''une structure : logos, couleurs, typographies, règles de mise en page.', 'Les supports doivent utiliser le bleu, la police et le logo du client, placés selon ses règles.'),
  ('v1', 'classe-inversee', 'Classe inversée', 'Pédagogie', 'Méthode dans laquelle l''apprenant découvre les notions en autonomie avant la séance, qui est consacrée à la pratique et aux échanges.', 'Les stagiaires regardent une vidéo sur le bilan la veille ; la séance est entièrement dédiée à un cas pratique.'),
  ('v1', 'classe-virtuelle', 'Classe virtuelle', 'Conception', 'Séance de formation à distance, en direct, animée par un formateur via un outil de visioconférence avec des fonctions interactives (sondage, tableau blanc, sous-groupes).', 'Une session de 90 minutes sur Teams avec travail en sous-groupes et quiz en direct.'),
  ('v1', 'coaching', 'Coaching', 'Prestations', 'Accompagnement individuel ou collectif centré sur un objectif professionnel précis. Le coach aide la personne à trouver ses propres solutions plutôt qu''à apprendre un contenu.', 'Six séances pour aider un nouveau responsable administratif à organiser son équipe.'),
  ('v1', 'cohorte', 'Cohorte', 'Ingénierie', 'Groupe d''apprenants qui démarrent et suivent le même parcours au même rythme.', 'La promotion de septembre et celle de janvier forment deux cohortes distinctes.'),
  ('v1', 'commanditaire', 'Commanditaire', 'Administratif', 'Personne ou structure qui passe la commande, décide et signe. Elle n''est pas forcément celle qui suit le projet ni celle qui bénéficie de la formation.', 'Le directeur général commande la formation ; la responsable RH la suit ; les comptables la suivent.'),
  ('v1', 'compensation-handicap', 'Compensation du handicap', 'Accessibilité', 'Ensemble des adaptations (matérielles, humaines, organisationnelles, pédagogiques) qui permettent à une personne en situation de handicap de suivre la formation dans des conditions équitables.', 'Un temps majoré pour les évaluations et des supports en gros caractères.'),
  ('v1', 'competence', 'Compétence', 'Besoin', 'Capacité à mobiliser des savoirs, des savoir-faire et des savoir-être pour agir efficacement dans une situation professionnelle donnée.', '« Établir une déclaration de TVA mensuelle dans les délais et sans erreur ».'),
  ('v1', 'conseil', 'Conseil', 'Prestations', 'Prestation d''expertise qui analyse une situation et formule des recommandations, sans transfert de compétences comme objectif principal.', 'Recommander l''organisation du plan de développement des compétences d''une PME.'),
  ('v1', 'convention-formation', 'Convention de formation', 'Administratif', 'Contrat entre l''organisme de formation et l''entreprise qui précise l''intitulé, les objectifs, la durée, les dates, le prix et les modalités de l''action.', 'La convention signée par l''employeur avant le démarrage, puis transmise à l''OPCO.'),
  ('v1', 'copil', 'COPIL (Comité de pilotage)', 'Projet', 'Instance de décision du projet qui réunit les décideurs à des étapes clés pour valider, arbitrer et réorienter.', 'Un COPIL au lancement, à mi-parcours et au bilan, avec le directeur, la RH et le formateur.'),
  ('v1', 'cpf', 'CPF (Compte personnel de formation)', 'Financement', 'Compte en euros rattaché à chaque actif, mobilisable pour des formations certifiantes (RNCP, RS) via la plateforme officielle. Une participation du titulaire peut être demandée selon les règles en vigueur.', 'Un salarié utilise son CPF pour préparer une certification bureautique enregistrée au RS.'),
  ('v1', 'critere', 'Critère', 'Objectifs', 'Élément mesurable qui permet de juger si un objectif est atteint : seuil, taux, délai, qualité attendue.', '« Sans erreur », « en moins de 20 minutes », « 8 écritures sur 10 correctes ».'),
  ('v1', 'dce', 'DCE (Dossier de consultation des entreprises)', 'Administratif', 'Ensemble des documents d''un appel d''offres : règlement de consultation, cahier des charges, critères de notation, pièces à fournir.', 'Le DCE d''une Région précise que la note pédagogique compte pour 60 % et le prix pour 40 %.'),
  ('v1', 'diagnostic', 'Diagnostic', 'Prestations', 'État des lieux rapide d''une situation pour identifier les problèmes, leurs causes et les priorités d''action.', 'Un diagnostic des compétences numériques d''une équipe avant de choisir les formations.'),
  ('v1', 'donnees-anonymisees', 'Données anonymisées', 'Juridique', 'Données dont on a retiré tout élément permettant d''identifier une personne, de manière irréversible.', 'Des bulletins de paie réels où noms, adresses et numéros de sécurité sociale ont été remplacés.'),
  ('v1', 'dossier-professionnel', 'Dossier professionnel', 'Certification', 'Document rédigé par le candidat à un titre professionnel, qui décrit des pratiques réelles en lien avec les compétences du référentiel. Il est remis au jury.', 'Un candidat décrit comment il a réalisé la clôture annuelle d''une entreprise.'),
  ('v1', 'e-learning', 'E-learning', 'Modalités', 'Formation en ligne suivie en autonomie, au rythme de l''apprenant, généralement sur une plateforme.', 'Un module de 30 minutes sur le RGPD, avec quiz final, accessible sur le LMS de l''entreprise.'),
  ('v1', 'ecart', 'Écart', 'Besoin', 'Différence observable entre ce qui est fait aujourd''hui et ce qui est attendu.', '15 % des factures sont saisies avec un mauvais taux de TVA, pour un objectif de 0 %.'),
  ('v1', 'emargement', 'Émargement (feuille d'')', 'Administratif', 'Document signé par chaque participant, par demi-journée, qui prouve sa présence. Il est exigé par les financeurs et par Qualiopi.', 'Une feuille papier ou une signature électronique matin et après-midi.'),
  ('v1', 'entretien-professionnel', 'Entretien professionnel', 'Réglementaire', 'Entretien obligatoire et périodique entre l''employeur et le salarié, consacré aux perspectives d''évolution et aux besoins de formation, selon la périodicité fixée par le Code du travail.', 'Plusieurs salariés expriment en entretien le souhait de monter en compétences sur la paie.'),
  ('v1', 'epi', 'EPI (Équipement de protection individuelle)', 'Réglementaire', 'Équipement porté pour se protéger d''un risque : casque, chaussures de sécurité, gilet, gants.', 'Le formateur doit porter des chaussures de sécurité pour animer dans un entrepôt.'),
  ('v1', 'evaluation-certificative', 'Évaluation certificative', 'Évaluation', 'Évaluation officielle qui conduit à la délivrance d''une certification, selon les modalités fixées par le certificateur.', 'La session d''examen d''un titre professionnel devant un jury.'),
  ('v1', 'evaluation-chaud', 'Évaluation à chaud (satisfaction)', 'Évaluation', 'Recueil de la satisfaction et du ressenti des participants immédiatement à la fin de la formation.', 'Un questionnaire en ligne rempli le dernier jour sur le contenu, l''animation et l''organisation.'),
  ('v1', 'evaluation-formative', 'Évaluation formative', 'Évaluation', 'Évaluation réalisée pendant l''apprentissage pour aider l''apprenant à progresser. Elle n''est pas notée à des fins de sanction.', 'Un quiz en fin de séquence suivi d''une correction collective.'),
  ('v1', 'evaluation-froid', 'Évaluation à froid', 'Évaluation', 'Évaluation réalisée plusieurs semaines ou mois après la formation, pour mesurer ce qui est réellement appliqué au poste.', 'Un questionnaire envoyé au participant et à son manager trois mois après.'),
  ('v1', 'evaluation-sommative', 'Évaluation sommative', 'Évaluation', 'Évaluation réalisée en fin de module ou de formation pour mesurer le niveau atteint par rapport aux objectifs.', 'Un cas pratique final noté, qui figure dans l''attestation de fin de formation.'),
  ('v1', 'fiche-poste', 'Fiche de poste', 'Besoin', 'Document qui décrit les missions, les activités, les responsabilités et les compétences requises pour un poste.', 'La fiche « assistant comptable » liste la saisie, le lettrage et les déclarations de TVA.'),
  ('v1', 'fichiers-sources', 'Fichiers sources', 'Conception', 'Fichiers de travail modifiables à l''origine d''un livrable (projet d''outil auteur, fichiers de mise en page, code), par opposition au livrable final figé.', 'Le client reçoit le package SCORM et aussi le projet modifiable pour le mettre à jour lui-même.'),
  ('v1', 'fle', 'FLE (Français langue étrangère)', 'Modalités', 'Enseignement du français à des personnes dont ce n''est pas la langue maternelle. Signale un besoin d''adapter les supports et le rythme.', 'Des consignes simplifiées et un lexique métier illustré pour un groupe allophone.'),
  ('v1', 'fne-formation', 'FNE-Formation', 'Financement', 'Dispositif de l''État qui cofinance des formations de salariés, notamment en cas de mutations économiques, selon des conditions et des priorités qui évoluent chaque année.', 'Une entreprise en transformation numérique mobilise ce dispositif via son OPCO.'),
  ('v1', 'formation-formateurs', 'Formation de formateurs', 'Prestations', 'Formation qui prépare des collaborateurs internes à animer eux-mêmes une formation auprès de leurs collègues.', 'Former trois référents internes qui déploieront ensuite le module dans toutes les agences.'),
  ('v1', 'gamification', 'Gamification', 'Pédagogie', 'Utilisation de mécanismes de jeu (points, badges, niveaux, missions) dans un contexte non ludique, pour renforcer l''engagement.', 'Un parcours e-learning où chaque module réussi débloque un badge et le niveau suivant.'),
  ('v1', 'grille-evaluation', 'Grille d''évaluation', 'Évaluation', 'Outil qui liste les critères observés et les niveaux de réussite attendus, pour évaluer de façon objective et identique pour tous.', 'Une grille qui note un entretien client simulé sur 5 critères, chacun sur 4 niveaux.'),
  ('v1', 'habilitation', 'Habilitation', 'Certification', 'Autorisation donnée par un certificateur à un organisme de formation pour préparer à sa certification et, selon les cas, organiser les évaluations.', 'RD Formation doit être habilitée par le certificateur avant de proposer une préparation éligible au CPF.'),
  ('v1', 'idcc', 'IDCC', 'Administratif', 'Identifiant de la convention collective, à quatre chiffres. Il permet de déterminer l''OPCO et les règles de branche.', 'IDCC 1486 pour les bureaux d''études techniques (Syntec).'),
  ('v1', 'indicateur', 'Indicateur', 'Besoin', 'Donnée mesurable qui permet de suivre l''évolution d''une situation et de vérifier l''effet d''une action.', 'Délai moyen de clôture mensuelle : 12 jours aujourd''hui, 7 jours visés.'),
  ('v1', 'indicateur-qualiopi', 'Indicateur Qualiopi', 'Réglementaire', 'Exigence précise du référentiel national qualité. Le référentiel compte 32 indicateurs répartis en 7 critères, chacun devant être prouvé lors de l''audit.', 'L''indicateur 4 impose de prouver l''analyse du besoin du bénéficiaire.'),
  ('v1', 'individualisation', 'Individualisation', 'Ingénierie', 'Adaptation du parcours à chaque apprenant : contenus, durée, rythme ou modalités, à partir de son positionnement et de ses objectifs.', 'Deux stagiaires d''une même cohorte suivent des modules différents selon leurs acquis.'),
  ('v1', 'ingenierie-formation', 'Ingénierie de formation', 'Ingénierie', 'Conception d''un dispositif de formation dans son ensemble : analyse du besoin, architecture, modalités, ressources, financement, évaluation du dispositif.', 'Concevoir un parcours de 400 heures en alternance menant à un titre professionnel.'),
  ('v1', 'ingenierie-pedagogique', 'Ingénierie pédagogique', 'Ingénierie', 'Conception des contenus et des situations d''apprentissage : objectifs, séquences, activités, supports, évaluations.', 'Scénariser la séquence « lire un bilan » avec ses activités, ses supports et son évaluation.'),
  ('v1', 'inter', 'Inter (entreprises)', 'Modalités', 'Formation qui réunit des participants de plusieurs structures différentes, sur un programme commun.', 'Une session Excel avec des salariés de cinq entreprises différentes.'),
  ('v1', 'intra', 'Intra (entreprise)', 'Modalités', 'Formation réservée aux salariés d''une seule structure, souvent adaptée à son contexte.', 'Une formation paie pour les huit gestionnaires d''un même groupe, avec leurs propres cas.'),
  ('v1', 'iteration', 'Itération', 'Projet', 'Cycle de correction d''un livrable : envoi, retours du client, modifications. Le nombre d''itérations incluses est fixé à l''avance.', 'Deux allers-retours de correction sont inclus sur le storyboard ; les suivants sont facturés.'),
  ('v1', 'jalon', 'Jalon', 'Projet', 'Point de passage clé d''un projet, daté, qui correspond à une livraison ou une décision.', 'Jalon 2 : validation du storyboard le 15 mars.'),
  ('v1', 'kirkpatrick', 'Kirkpatrick (modèle de)', 'Évaluation', 'Modèle d''évaluation en quatre niveaux : 1 réaction (satisfaction), 2 apprentissage (acquis), 3 comportement (application au poste), 4 résultats (effets sur la structure).', 'Niveau 3 : le manager constate que les notes de frais sont désormais conformes.'),
  ('v1', 'licence-utilisation', 'Licence d''utilisation', 'Juridique', 'Autorisation d''utiliser une œuvre selon des conditions définies, sans transfert de propriété. L''auteur reste propriétaire.', 'Le client peut diffuser le module à ses salariés, mais pas le revendre ni le modifier.'),
  ('v1', 'livrable', 'Livrable', 'Projet', 'Production concrète et identifiable remise au client à une étape du projet.', 'Un scénario pédagogique au format Word, un package SCORM, un rapport d''audit.'),
  ('v1', 'livret-apprenant', 'Livret apprenant', 'Ingénierie', 'Document remis à l''apprenant qui présente le parcours, les objectifs, le calendrier, les règles et sert de support de suivi.', 'Un livret avec la carte du parcours, les dates, le règlement intérieur et un espace de prise de notes.'),
  ('v1', 'lms', 'LMS (Learning Management System)', 'Conception', 'Plateforme de gestion de la formation en ligne : diffusion des contenus, inscriptions, suivi de la progression, évaluations.', 'Moodle, 360Learning ou un LMS développé sur mesure.'),
  ('v1', 'ludopedagogie', 'Ludopédagogie', 'Pédagogie', 'Utilisation du jeu comme méthode d''apprentissage, où le jeu lui-même porte l''objectif pédagogique.', 'Un escape game où il faut équilibrer un bilan pour ouvrir le dernier cadenas.'),
  ('v1', 'maintenance', 'Maintenance', 'Projet', 'Mise à jour et correction d''un livrable après sa livraison (évolution réglementaire, bug, changement d''outil).', 'Mettre à jour les taux de cotisations d''un module paie au 1er janvier.'),
  ('v1', 'maquette', 'Maquette', 'Conception', 'Prototype visuel d''un écran ou d''un module, qui montre le rendu final avant la production complète.', 'Trois écrans types du module présentés au client pour valider le design.'),
  ('v1', 'matrice-alignement', 'Matrice d''alignement', 'Ingénierie', 'Tableau qui vérifie la cohérence entre objectifs, activités et évaluations : chaque objectif est travaillé et évalué.', 'Une ligne par objectif, une colonne pour l''activité associée et une pour l''évaluation correspondante.'),
  ('v1', 'methodes-actives', 'Méthodes actives', 'Pédagogie', 'Méthodes où l''apprenant construit ses savoirs en agissant : cas pratiques, mises en situation, projets, jeux de rôle.', 'Les participants construisent eux-mêmes un tableau de bord à partir de données réelles.'),
  ('v1', 'methodes-pedagogiques', 'Méthodes pédagogiques', 'Pédagogie', 'Manières d''organiser l''apprentissage. On distingue généralement les méthodes expositive, démonstrative, interrogative, active et expérientielle.', 'Démontrer une manipulation Excel, puis faire refaire l''exercice par les participants.'),
  ('v1', 'microlearning', 'Microlearning', 'Modalités', 'Format d''apprentissage très court (souvent moins de 5 minutes) centré sur une seule notion, consultable facilement, souvent sur mobile.', 'Une vidéo de 3 minutes sur « comment lettrer un compte fournisseur ».'),
  ('v1', 'mobile-first', 'Mobile first', 'Conception', 'Principe de conception qui pense d''abord l''affichage sur smartphone, puis l''adapte aux écrans plus grands.', 'Un module lisible et utilisable sur téléphone pour des techniciens sur chantier.'),
  ('v1', 'module', 'Module', 'Ingénierie', 'Unité d''un parcours, cohérente et centrée sur un ensemble de compétences, composée de plusieurs séquences.', 'Module « Opérations de fin d''exercice », 35 heures, composé de 5 séquences.'),
  ('v1', 'motion-design', 'Motion design', 'Conception', 'Création de vidéos animées à partir d''éléments graphiques (textes, formes, icônes) pour expliquer un concept.', 'Une animation de 90 secondes qui montre le circuit d''une facture de sa réception au paiement.'),
  ('v1', 'naf', 'NAF (code)', 'Administratif', 'Code de la nomenclature d''activités française, attribué par l''INSEE, qui identifie l''activité principale d''une entreprise (aussi appelé code APE).', '85.59A : formation continue d''adultes.'),
  ('v1', 'nda', 'NDA (Numéro de déclaration d''activité)', 'Administratif', 'Numéro attribué par l''administration (DREETS) à tout organisme de formation déclaré. Il doit figurer sur les conventions et documents contractuels.', 'Un OF qui sous-traite une formation à RD Formation communique son NDA dans la convention.'),
  ('v1', 'niveau-interactivite', 'Niveau d''interactivité', 'Conception', 'Degré d''engagement demandé à l''apprenant dans un module numérique, de la simple consultation à l''immersion dans un scénario complexe.', 'Niveau 1 : lire et cliquer « suivant » ; niveau 3 : prendre des décisions dans une simulation.'),
  ('v1', 'niveau-qualification', 'Niveau de qualification', 'Certification', 'Classement national des certifications en 8 niveaux : 3 (CAP), 4 (Bac), 5 (Bac+2), 6 (Bac+3 ou 4), 7 (Bac+5), 8 (doctorat).', 'Le titre Comptable assistant est de niveau 4.'),
  ('v1', 'note-de-cadrage', 'Note de cadrage', 'Besoin', 'Document rédigé par le prestataire après l''analyse de la demande. Il reformule le besoin, fixe le périmètre, les objectifs et les conditions, et est validé par le client avant la proposition.', 'Une note de 3 pages signée par le client qui sert de référence en cas de désaccord.'),
  ('v1', 'objectif-operationnel', 'Objectif opérationnel', 'Objectifs', 'Ce que la personne devra réaliser concrètement à son poste après la prestation.', '« Réaliser seule les déclarations de TVA mensuelles de ses dossiers ».'),
  ('v1', 'objectif-pedagogique', 'Objectif pédagogique', 'Objectifs', 'Ce que l''apprenant sera capable de faire à l''issue d''une séquence de formation, formulé avec un verbe observable, des conditions et des critères.', '« Calculer la TVA due à partir de 20 factures, avec le logiciel, sans erreur ».'),
  ('v1', 'objectif-strategique', 'Objectif stratégique', 'Objectifs', 'Résultat attendu pour la structure, lié à son projet ou à ses enjeux.', '« Internaliser la gestion de la TVA pour réduire les coûts d''externalisation de 30 % ».'),
  ('v1', 'opco', 'OPCO (Opérateur de compétences)', 'Financement', 'Organisme agréé par l''État qui accompagne les entreprises d''une branche professionnelle et finance une partie de leurs formations. Il en existe 11, l''entreprise dépend de celui de sa branche.', 'Un restaurant relève d''AKTO ; une pharmacie d''officine relève de l''OPCO EP.'),
  ('v1', 'parcours-adaptatif', 'Parcours adaptatif', 'Ingénierie', 'Parcours dont le contenu et l''ordre s''ajustent automatiquement ou manuellement selon les résultats et le comportement de l''apprenant.', 'Un échec au quiz redirige vers une remédiation ; une réussite ouvre directement le module suivant.'),
  ('v1', 'plan-action', 'Plan d''action', 'Prestations', 'Liste d''actions priorisées, avec responsables, échéances et indicateurs, issue d''un audit ou d''un diagnostic.', '12 actions classées par priorité pour se mettre en conformité Qualiopi en 3 mois.'),
  ('v1', 'plan-developpement-competences', 'Plan de développement des compétences', 'Financement', 'Ensemble des actions de formation décidées par l''employeur pour ses salariés, financées principalement sur les fonds de l''entreprise.', 'L''entreprise inscrit la formation Excel de son équipe dans son plan annuel.'),
  ('v1', 'pmr', 'PMR (Personne à mobilité réduite)', 'Accessibilité', 'Toute personne qui éprouve des difficultés à se déplacer. Les locaux accessibles aux PMR disposent d''accès adaptés (rampe, ascenseur, sanitaires).', 'Vérifier que la salle au 2e étage est desservie par un ascenseur.'),
  ('v1', 'positionnement', 'Positionnement', 'Évaluation', 'Évaluation d''entrée qui mesure les acquis et les besoins de chaque apprenant pour adapter son parcours. On parle aussi d''évaluation diagnostique.', 'Un test Excel de 20 minutes qui oriente chaque stagiaire vers le niveau adapté.'),
  ('v1', 'prerequis', 'Prérequis', 'Pédagogie', 'Connaissances ou compétences nécessaires avant d''entrer en formation pour pouvoir la suivre avec profit.', '« Savoir utiliser un tableur pour saisir et trier des données ».'),
  ('v1', 'prestation', 'Prestation', 'Prestations', 'Service vendu par RD Formation. Le questionnaire distingue cinq familles : formation, prestation ponctuelle, conception de module, ingénierie, démarche certifiante.', 'Une même demande peut combiner une ingénierie de parcours et l''animation de la formation.'),
  ('v1', 'prise-en-charge', 'Prise en charge', 'Financement', 'Accord d''un financeur (OPCO, État, Région, France Travail) pour financer tout ou partie d''une formation, obtenu en principe avant le démarrage.', 'L''OPCO accorde une prise en charge de 1 800 € sur un coût total de 2 400 €.'),
  ('v1', 'pro-a', 'Pro-A', 'Financement', 'Reconversion ou promotion par l''alternance : dispositif qui permet à un salarié de se former en alternance pour évoluer ou changer de métier, sous conditions.', 'Une secrétaire devient assistante comptable via Pro-A tout en restant dans son entreprise.'),
  ('v1', 'progression-pedagogique', 'Progression pédagogique', 'Ingénierie', 'Ordonnancement logique des séquences et des séances d''un parcours, du simple au complexe, avec leur durée.', 'Un tableau qui planifie 35 séances sur 10 semaines avec objectif et durée de chacune.'),
  ('v1', 'propriete-intellectuelle', 'Propriété intellectuelle', 'Juridique', 'Droits protégeant les créations de l''esprit, dont les droits d''auteur sur les supports, scénarios, vidéos et modules pédagogiques.', 'Sauf clause contraire, les supports créés par RD Formation restent sa propriété.'),
  ('v1', 'proposition-technique-financiere', 'Proposition technique et financière', 'Administratif', 'Document de réponse qui présente la compréhension du besoin, la solution proposée, la méthode, le planning, l''équipe et le prix.', 'Un dossier de 10 pages remis en réponse à un appel d''offres.'),
  ('v1', 'qqoqcp', 'QQOQCP', 'Besoin', 'Méthode de questionnement : Qui, Quoi, Où, Quand, Comment, Pourquoi. Elle permet de relancer une réponse vague en entretien.', '« Vous parlez d''erreurs : qui les commet, sur quoi, depuis quand, et comment les repérez-vous ? »'),
  ('v1', 'qualiopi', 'Qualiopi', 'Réglementaire', 'Certification qualité obligatoire pour les organismes de formation qui veulent accéder aux fonds publics ou mutualisés (OPCO, CPF, État, Régions). Elle repose sur le référentiel national qualité.', 'Sans Qualiopi, une formation ne peut pas être financée par le CPF.'),
  ('v1', 'reac', 'REAC', 'Certification', 'Référentiel emploi, activités, compétences d''un titre professionnel du ministère du Travail. Il décrit l''emploi, les activités types et les compétences évaluées.', 'Le REAC du titre Gestionnaire comptable et fiscal structure les épreuves de l''examen.'),
  ('v1', 'referent-handicap', 'Référent handicap', 'Accessibilité', 'Personne chargée d''accueillir, d''informer et d''organiser les adaptations pour les personnes en situation de handicap.', 'Le référent handicap de l''entreprise et celui de RD Formation définissent ensemble les aménagements.'),
  ('v1', 'referentiel-activites', 'Référentiel d''activités', 'Ingénierie', 'Description des activités et tâches réalisées dans un métier, indépendamment de la formation.', '« Activité 1 : assurer la tenue comptable ; tâches : saisir, lettrer, rapprocher ».'),
  ('v1', 'referentiel-competences', 'Référentiel de compétences', 'Ingénierie', 'Liste structurée des compétences nécessaires pour exercer les activités d''un métier, avec leurs critères d''évaluation.', '« Réaliser un rapprochement bancaire : les écarts sont identifiés et justifiés ».'),
  ('v1', 'rgaa', 'RGAA', 'Accessibilité', 'Référentiel général d''amélioration de l''accessibilité : référentiel français qui décline les critères techniques d''accessibilité des contenus numériques.', 'Un module conforme au RGAA est utilisable avec un lecteur d''écran.'),
  ('v1', 'rgpd', 'RGPD', 'Réglementaire', 'Règlement général sur la protection des données (règlement européen 2016/679). Il encadre la collecte et l''usage des données personnelles.', 'Les résultats de tests des stagiaires sont des données personnelles à protéger et à conserver pour une durée limitée.'),
  ('v1', 'rncp', 'RNCP', 'Certification', 'Répertoire national des certifications professionnelles, géré par France Compétences. Il recense les diplômes, titres et certificats classés par niveau de qualification.', 'Les titres Comptable assistant et Gestionnaire comptable et fiscal sont enregistrés au RNCP.'),
  ('v1', 'roi', 'ROI (Retour sur investissement)', 'Évaluation', 'Mesure financière de l''effet d''une formation : gains obtenus comparés au coût engagé.', 'Une formation de 3 000 € qui évite 9 000 € de pénalités de retard a un ROI de 200 %.'),
  ('v1', 'rs', 'RS (Répertoire spécifique)', 'Certification', 'Répertoire de France Compétences qui recense des certifications et habilitations complémentaires à un métier, sans niveau de qualification.', 'Une certification bureautique ou la certification CléA sont enregistrées au RS.'),
  ('v1', 'savoir-etre', 'Savoir-être', 'Besoin', 'Comportements et attitudes professionnels attendus dans une situation de travail. On parle aussi de compétences comportementales ou relationnelles.', '« Reformuler la demande d''un client mécontent avant de proposer une solution ».'),
  ('v1', 'scorm', 'SCORM', 'Conception', 'Norme technique qui permet à un module e-learning de fonctionner dans n''importe quel LMS compatible et d''y remonter la progression et les scores. Versions courantes : 1.2 et 2004.', 'Un package SCORM déposé dans Moodle qui enregistre le score et le statut « terminé ».'),
  ('v1', 'scenario-pedagogique', 'Scénario pédagogique', 'Conception', 'Description détaillée du déroulement d''une formation ou d''un module : objectifs, activités, méthodes, durées, ressources et évaluations, étape par étape.', 'Un tableau qui décrit les 12 étapes d''une séance de 3 heures.'),
  ('v1', 'seance', 'Séance', 'Ingénierie', 'Plus petite unité de temps pédagogique, réalisée en une fois, avec un objectif précis.', 'Séance de 3 heures : « Enregistrer les factures d''achat ».'),
  ('v1', 'sequence', 'Séquence', 'Ingénierie', 'Ensemble de séances organisées autour d''un objectif commun, à l''intérieur d''un module.', 'Séquence « TVA » composée de 4 séances.'),
  ('v1', 'serious-game', 'Serious game', 'Conception', 'Jeu numérique conçu avec une finalité pédagogique ou professionnelle, qui immerge l''apprenant dans un scénario.', 'Un jeu où l''apprenant gère la trésorerie d''une entreprise fictive pendant 12 mois.'),
  ('v1', 'siret', 'SIRET', 'Administratif', 'Identifiant à 14 chiffres d''un établissement : les 9 chiffres du SIREN de l''entreprise suivis de 5 chiffres propres à l''établissement.', 'Une entreprise avec deux agences a un seul SIREN et deux SIRET.'),
  ('v1', 'situation-travail', 'Situation de travail', 'Besoin', 'Contexte réel dans lequel une compétence est mobilisée : tâche, environnement, outils, contraintes.', '« Préparer la clôture mensuelle en fin de mois, sous pression de délai, avec le logiciel Sage ».'),
  ('v1', 'sous-traitance', 'Sous-traitance', 'Administratif', 'Situation où un organisme de formation confie la réalisation d''une action à un autre prestataire, tout en restant responsable vis-à-vis du client et de Qualiopi.', 'Un OF confie à RD Formation l''animation d''un module paie de son parcours.'),
  ('v1', 'storyboard', 'Storyboard', 'Conception', 'Document qui décrit écran par écran un module numérique : textes, médias, interactions, navigation et feedbacks.', 'Une page par écran avec le visuel prévu, le texte à l''écran, la voix off et les boutons.'),
  ('v1', 'subrogation', 'Subrogation', 'Financement', 'Mécanisme par lequel le financeur paie directement l''organisme de formation, sans que l''entreprise avance les frais.', 'L''OPCO règle directement la facture à RD Formation ; l''entreprise ne paie que le reste à charge.'),
  ('v1', 'sur-mesure', 'Sur-mesure', 'Modalités', 'Formation conçue spécifiquement pour un client à partir de son besoin, de son contexte et de ses documents.', 'Un module construit sur les procédures et les vrais dossiers du cabinet.'),
  ('v1', 'synchrone', 'Synchrone', 'Modalités', 'Modalité où formateur et apprenants sont connectés en même temps, à distance ou en présentiel. Son contraire est `asynchrone`.', 'Une classe virtuelle est synchrone ; un module e-learning est asynchrone.'),
  ('v1', 'transfert', 'Transfert (des acquis)', 'Évaluation', 'Application effective au poste de travail de ce qui a été appris en formation. C''est la finalité de toute formation professionnelle.', 'Un mois après, la stagiaire utilise seule les tableaux croisés dynamiques pour son reporting.'),
  ('v1', 'tuteur', 'Tuteur', 'Modalités', 'Salarié expérimenté qui accompagne un apprenant en entreprise : accueil, transmission, suivi, lien avec l''organisme de formation.', 'Le chef comptable suit l''apprentie et participe aux bilans trimestriels.'),
  ('v1', 'vae', 'VAE (Validation des acquis de l''expérience)', 'Certification', 'Dispositif qui permet d''obtenir tout ou partie d''une certification en faisant reconnaître son expérience, sans suivre la formation complète.', 'Une assistante avec 8 ans d''expérience obtient un titre par VAE après un entretien avec le jury.'),
  ('v1', 'xapi', 'xAPI', 'Conception', 'Norme de suivi des apprentissages plus récente que SCORM. Elle enregistre des activités variées, y compris hors LMS, dans un entrepôt de données (LRS).', 'Suivre qu''un apprenant a regardé une vidéo, réussi une simulation et participé à un atelier.');
